L(check_key):
        cmeq    v0.4s, v12.4s, v26.4s
        cmeq    v1.4s, v14.4s, v26.4s
        cmeq    v2.4s, v15.4s, v26.4s
        cmeq    v3.4s, v17.4s, v26.4s
        orr     v4.16b, v0.16b, v1.16b
        orr     v5.16b, v2.16b, v3.16b
        orr     v4.16b, v4.16b, v5.16b
        umaxv   s4, v4.4s
        fmov    w16, s4
        cbnz    w16, L(check_hi)

L(next_key):
        subs    w9, w9, #1
        b.eq    L(finished_nothing)
        add     w13, w13, #16
        tbnz    w13, #8, L(carry_hi)
