L(carry_hi):
        // the prep that ran alongside this batch used a wrapped L0hi: discard
        // it, recompute mid/lo state, re-prep the other table, and continue
        and     w13, w13, #0xFF
        str     w13, [x0, #16]
        rev     w14, w14
        adds    w14, w14, #1
        rev     w14, w14
        b.cc    L(redo_mid)
        rev     w15, w15
        add     w15, w15, #1
        rev     w15, w15
        // recompute pre_B_0/pre_S1 (lo changed), then fall through
        mov     w16, #0x8B1D
        movk    w16, #0xBF0A, lsl #16
        add     w2, w15, w16
        ror     w2, w2, #3
        str     w2, [sp, #160]
        mov     w16, #0x5639
        movk    w16, #0x1523, lsl #16
        add     w3, w2, w16
        ror     w3, w3, #29
        str     w3, [sp, #164]
L(redo_mid):
        ldr     w2, [sp, #160]
        ldr     w3, [sp, #164]
        add     w16, w2, w3
        add     w17, w14, w16
        neg     w2, w16
        ror     w17, w17, w2
        str     w17, [sp, #168]
        mov     w2, #0x44D5
        movk    w2, #0xF450, lsl #16
        add     w2, w2, w3
        add     w2, w2, w17
        ror     w2, w2, #29
        str     w2, [sp, #172]
        add     w16, w17, w2
        str     w16, [sp, #176]
        str     w13, [sp, #180]
        bl      L(scalar_prep)              // into [x12], the stale table
        b       L(swap_tables)

